def solve():
    edges = [
        (0,1), (0,2), (1,2),
        (3,4), (3,5), (4,5),
        (6,7), (6,8), (7,8),
        (0,3), (1,4), (2,5),
        (3,6), (4,7), (5,8)
    ]

    def search(idx, current_labels, used_labels, used_diffs):
        if idx == 9:
            return current_labels

        for l in range(16):
            if l in used_labels:
                continue

            # Check edges connected to this vertex that go to already labeled vertices
            valid = True
            new_diffs = set()
            for u, v in edges:
                if u == idx and v < idx:
                    diff = abs(l - current_labels[v])
                    if diff in used_diffs or diff in new_diffs:
                        valid = False
                        break
                    new_diffs.add(diff)
                elif v == idx and u < idx:
                    diff = abs(l - current_labels[u])
                    if diff in used_diffs or diff in new_diffs:
                        valid = False
                        break
                    new_diffs.add(diff)

            if valid:
                used_labels.add(l)
                used_diffs.update(new_diffs)
                current_labels.append(l)

                res = search(idx + 1, current_labels, used_labels, used_diffs)
                if res:
                    return res

                current_labels.pop()
                used_diffs.difference_update(new_diffs)
                used_labels.remove(l)

    return search(0, [], set(), set())

print(solve())
